#define RB_CAP 64

struct ring {
    uint8_t buf[RB_CAP];
    size_t head;
    size_t tail;
};

#ifdef RB_TRACE
static void rb_trace(const char *tag, size_t n);
#endif

void rb_init(struct ring *r)
{
    r->head = 0;
    r->tail = 0;
}

#if RB_CAP > 32
static size_t rb_mask(size_t i)
{
    return i & (RB_CAP - 1u);
}

int rb_push(struct ring *r, uint8_t v)
{
    size_t next = rb_mask(r->head + 1u);
    if (next == r->tail) {
        return -1;
    }
    r->buf[r->head] = v;
    r->head = next;
    return 0;
}

int rb_pop(struct ring *r, uint8_t *out)
{
    if (r->head == r->tail) {
        return -1;
    }
    *out = r->buf[r->tail];
    r->tail = rb_mask(r->tail + 1u);
    return 0;
}

