#define IS_SPACE(c)  ((c) == ' ' || (c) == '\t' || (c) == '\n')
#define IS_DIGIT(c)  ((c) >= '0' && (c) <= '9')

enum tok_kind { TOK_EOF, TOK_WORD, TOK_NUM, TOK_PUNCT };

struct token {
    enum tok_kind kind;
    const char *start;
    size_t len;
};

#define TOK_MAKE(k, s, n) ((struct token){ (k), (s), (n) })

struct token tok_next(const char **cur)
{
    const char *p = *cur;
    const char *s;

    while (*p != '\0' && IS_SPACE(*p)) {
        p++;
    }
    if (*p == '\0') {
        *cur = p;
        return TOK_MAKE(TOK_EOF, p, 0);
    }
    if (IS_DIGIT(*p)) {
        s = p;
        while (IS_DIGIT(*p)) {
            p++;
        }
        *cur = p;
        return TOK_MAKE(TOK_NUM, s, (size_t)(p - s));
    }
    if (*p == ',' || *p == ';' || *p == '=') {
        *cur = p + 1;
        return TOK_MAKE(TOK_PUNCT, p);
    }
    s = p;
    while (*p != '\0' && !IS_SPACE(*p)) {
        p++;
    }
    *cur = p;
    return TOK_MAKE(TOK_WORD, s, (size_t)(p - s));
}

