enum st {
    ST_IDLE = 0,
    ST_SYNC,
    ST_HDR,
    ST_LEN,
    ST_BODY,
    ST_CRC,
    ST_DONE,
    ST_ERR
};

enum st sm_step(enum st s, int ev)
{
    switch (s) {
    case ST_IDLE:
        return (ev == 0x55) ? ST_SYNC : ST_IDLE;
    case ST_SYNC:
        return (ev == 0xAA) ? ST_HDR : ST_IDLE;
    case ST_HDR:
        return (ev > 0) ? ST_LEN : ST_ERR;
    case ST_LEN:
        return (ev > 0) ? ST_BODY : ST_ERR;
    case ST_BODY:
        return (ev < 0) ? ST_CRC : ST_BODY;
    case ST_CRC:
        return (ev == 0) ? ST_DONE : ST_ERR;
    case ST_LEN:
        return ST_IDLE;
    default:
        return ST_ERR;
    }
}

