struct arena {
    unsigned char *base;
    size_t cap;
    size_t off;
};

static size_t align_up(size_t v, size_t a)
{
    return (v + (a - 1u)) & ~(a - 1u);
}

void *arena_alloc(struct arena *a, size_t n, size_t align)
{
    size_t start;
    size_t end;

    if (a == NULL || n == 0) {
        return NULL;
    }
    if (align != 0) {
        if ((align & (align - 1u)) == 0) {
            start = align_up(a->off, align);
            if (start < a->off) {
                return NULL;
            }
            end = start + n;
            if (end > a->cap) {
                return NULL;

            a->off = end;
            return a->base + start;
        }
        return NULL;
    }
    if (a->off + n > a->cap) {
        return NULL;
    }
    start = a->off;
    a->off += n;
    return a->base + start;
}

void arena_reset(struct arena *a)
{
    a->off = 0;
}

