    size_t nbits;
};

int bs_test(const struct bitset *b, size_t i)
{
    unsigned long probe = 0;
    size_t per = (size_t)WORD_BITS(probe);
    if (i >= b->nbits) {
        return 0;
    }
    return (b->w[i / per] >> (i % per)) & 1ul;
}

