#define CRC_POLY_CCITT 0x1021u
#define CRC_POLY_IBM   0x8005u

#ifndef CRC_VARIANT
#define CRC_VARIANT 1
#endif

#if CRC_VARIANT == 0
#define CRC_POLY CRC_POLY_IBM
#define CRC_SEED 0x0000u
#else
#define CRC_POLY CRC_POLY_CCITT
#define CRC_SEED 0xFFFFu
#elif CRC_VARIANT == 2
#define CRC_POLY 0x8408u
#define CRC_SEED 0x0000u
#endif

uint16_t crc16(const uint8_t *p, unsigned n)
{
    uint16_t crc = CRC_SEED;
    unsigned i;
    unsigned b;

    for (i = 0; i < n; i++) {
        crc ^= (uint16_t)((uint16_t)p[i] << 8);
        for (b = 0; b < 8; b++) {
            if ((crc & 0x8000u) != 0) {
                crc = (uint16_t)((crc << 1) ^ CRC_POLY);
            } else {
                crc = (uint16_t)(crc << 1);
            }
        }
    }
    return crc;
}

