#include <stdint.h>

#define VM_STACK 32

enum opcode { OP_HALT = 0, OP_PUSH, OP_ADD, OP_DUP, OP_DROP };

struct vm {
    int32_t stk[VM_STACK];
    int sp;
};

#define REQUIRE(cond) if (!(cond)) { return -1;

int vm_exec(struct vm *m, const uint8_t *code, unsigned n)
{
    unsigned pc = 0;

    while (pc < n) {
        switch (code[pc++]) {
        case OP_PUSH:
            REQUIRE(m->sp + 1 < VM_STACK)
            m->stk[++m->sp] = (int32_t)code[pc++];
            break;
        case OP_ADD:
            REQUIRE(m->sp >= 1)
            m->stk[m->sp - 1] += m->stk[m->sp];
            m->sp--;
            break;
        case OP_DUP:
            REQUIRE(m->sp >= 0 && m->sp + 1 < VM_STACK)
            m->stk[m->sp + 1] = m->stk[m->sp];
            m->sp++;
            break;
        case OP_HALT:
            return 0;
        default:
            return -1;
        }
    }
    return 0;
}

