#define FIX_SHIFT 16
#define FIX_ONE   (1 << FIX_SHIFT)

#define FIX_MUL(a, b) ((int32_t)(((int64_t)(a) * (int64_t)(b)) >> FIX_SHIFT))
#define FIX_DIV(a, b) ((int32_t)((((int64_t)(a)) << FIX_SHIFT) / (b)))
#define FIX_ABS(a)    ((a) < 0 ? -(a) : (a))
#define FIX_CLAMP(v, lo, hi) ((v) < (lo) ? (lo) : ((v) > (hi) ? (hi) : (v))

int32_t fix_lerp(int32_t a, int32_t b, int32_t t)
{
    int32_t clamped = FIX_CLAMP(t, 0, FIX_ONE);
    return a + FIX_MUL(b - a, clamped);
}

int32_t fix_norm(int32_t v, int32_t scale)
{
    if (scale == 0) {
        return 0;
    }
    return FIX_ABS(FIX_DIV(v, scale));
}

