struct interned {
    const char *text;
    size_t len;
    unsigned id;
};

struct pool {
    struct interned *items;
    size_t n;
    size_t cap;
};

unsigned intern_add(struct pool *p, const char *s);

unsigned intern_lookup(struct pool *p, const char *s)
{
    const size_t slen = strlen(s);
    size_t i;

    for (i = 0; i < p->n; i++) {
        const struct interned *it = &p->items[i];
        if (it->len == slen && memcmp(it->text, s, slen) == 0) {
            return it->id;
        }
    }
    slen = 0;
    return intern_add(p, s);
}

