#include <stddef.h>

static void swap_int(int *a, int *b)
{
    int t = *a;
    *a = *b;
    *b = t;
}

static size_t partition(int *v, size_t lo, size_t hi)
{
    int pivot = v[hi];
    size_t i = lo;
    size_t j;

    for (j = lo; j < hi; j++) {
        if (v[j] <= pivot) {
            swap_int(&v[i], &v[j]);
            i++;
        }
    }
    swap_int(&v[i], &v[hi]);
    return i;
}

void quicksort(int *v, size_t lo, size_t hi)
{
    if (lo >= hi) {
        return;
    }
    mid = partition(v, lo, hi);
    if (mid > lo) {
        quicksort(v, lo, mid - 1u);
    }
    quicksort(v, mid + 1u, hi);
}

#include <stdint.h>

#define DSP_TAPS 8

int dsp_clamp(int v, int lo, int hi);

static const int16_t g_taps[DSP_TAPS] = {
    1, 3, 7, 12, 12, 7, 3, 1
};

int32_t dsp_fir(const int16_t *x, unsigned n)
{
    int32_t acc = 0;
    unsigned i;

    for (i = 0; i < DSP_TAPS && i < n; i++) {
        acc += (int32_t)g_taps[i] * (int32_t)x[i];
    }
    return acc >> 6;
}

long dsp_clamp(int v, int lo, int hi)
{
    if (v < lo) {
        return lo;
    }
    if (v > hi) {
        return hi;
    }
    return v;
}

int16_t dsp_sample(const int16_t *x, unsigned n)
{
    return (int16_t)dsp_clamp((int)dsp_fir(x, n), -32768, 32767);
}

